package brand

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"path"
	"regexp"
	"strings"

	"github.com/go-playground/errors/v5"
)

// Execer runs an external command in a directory with extra environment entries and
// returns its combined output; the check package's OSExec is one.
type Execer interface {
	Run(ctx context.Context, dir string, extraEnv []string, name string, args ...string) ([]byte, error)
}

// The palette is generated by Angular Material's own generator, the theme-color
// schematic of the version the workspace has installed, so the palette is the one that
// version's components are drawn for and the brand's exact color is its source. The
// schematic is run through the workspace's own Angular command line, with every answer
// given as a flag and no prompt asked.
const (
	ngBin             = "node_modules/.bin/ng"
	prettierBin       = "node_modules/.bin/prettier"
	themeSchematic    = "@angular/material:theme-color"
	themeSchematicDir = "node_modules/@angular/material/schematics/ng-generate/theme-color"
)

// generatedFrom reads the primary color a generated palette file says it was generated
// from, in the note the schematic writes at its top.
var generatedFrom = regexp.MustCompile(`generated from primary: (#[0-9a-fA-F]{6})`)

// palette generates the theme's palette from the brand's primary color into the browser
// application's source root, and reports whether the palette of that color is there
// afterwards.
// The schematic needs the workspace's packages installed: where they are not, a palette
// already generated from the same color stands, and any other is left with what to do.
func (w *writer) palette(ctx context.Context, exec Execer, r *declared) (bool, error) {
	file := path.Join(r.Source, paletteFile)
	before, err := os.ReadFile(w.a.Abs(file))
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return false, errors.Wrap(err, "os.ReadFile()")
	}
	color := r.declaration.PrimaryColor
	if !exists(w.a.Abs(path.Join(r.Workspace, ngBin))) || !exists(w.a.Abs(path.Join(r.Workspace, themeSchematicDir))) {
		if m := generatedFrom.FindSubmatch(before); len(m) == 2 && strings.EqualFold(string(m[1]), color) {
			w.writes = append(w.writes, Write{File: file, State: Unchanged})

			return true, nil
		}
		w.left(file, fmt.Sprintf("the palette is generated by Angular Material's theme-color schematic, which comes with the packages of %s, and they are not installed (no %s); install them and run impulse brand again", r.Workspace, path.Join(r.Workspace, ngBin)))

		return false, nil
	}

	directory := strings.TrimPrefix(strings.TrimPrefix(r.Source, r.Workspace), "/")
	args := []string{"generate", themeSchematic, "--primary-color=" + color, "--directory=" + directory + "/", "--is-scss", "--include-high-contrast=false", "--interactive=false", "--force"}
	workspace := w.a.Abs(r.Workspace)
	if out, err := exec.Run(ctx, workspace, []string{"NG_CLI_ANALYTICS=false"}, w.a.Abs(path.Join(r.Workspace, ngBin)), args...); err != nil {
		return false, errors.Newf("Angular Material's theme-color schematic could not generate the palette of %s from %s (ng %s in %s): %s", r.Dir, color, strings.Join(args, " "), r.Workspace, lastLine(out, err))
	}
	// The schematic writes the file its own way; the workspace's prettier, where the
	// install brought one, leaves it as impulse check holds every browser file.
	if formatter := w.a.Abs(path.Join(r.Workspace, prettierBin)); exists(formatter) {
		if out, err := exec.Run(ctx, workspace, nil, formatter, "--write", path.Join(directory, paletteFile)); err != nil {
			return false, errors.Newf("prettier could not format the generated palette %s: %s", file, lastLine(out, err))
		}
	}
	after, err := os.ReadFile(w.a.Abs(file))
	if err != nil {
		return false, errors.Newf("Angular Material's theme-color schematic ran and wrote no %s (ng %s in %s)", file, strings.Join(args, " "), r.Workspace)
	}
	state := Written
	if bytes.Equal(before, after) {
		state = Unchanged
	}
	w.writes = append(w.writes, Write{File: file, State: state})

	return true, nil
}

// theme makes the generated palette the theme's first and names it in the list the
// picker offers.
func (w *writer) theme(r *declared) error {
	if err := w.edit(path.Join(r.Source, themeFile), "the theme's first palette", setTheme); err != nil {
		return err
	}

	return w.edit(path.Join(r.Source, appConfigFile), "the palette's name in the picker", func(text string) (string, []string) {
		return setPaletteLabel(text, r.declaration.Name)
	})
}

// exists reports whether something is at the absolute path.
func exists(abs string) bool {
	_, err := os.Stat(abs)

	return err == nil
}

// lastLine is the last line a failed command wrote, or its error where it wrote none.
func lastLine(out []byte, err error) string {
	lines := strings.Split(strings.TrimSpace(string(out)), "\n")
	if last := strings.TrimSpace(lines[len(lines)-1]); last != "" {
		return last
	}

	return errors.Cause(err).Error()
}
